const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const get=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},put=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){console.warn('Storage unavailable',e)}};let token=(()=>{try{return localStorage.getItem('ping_token')}catch{return null}})(),me=null,friends=[],msgs=[],page='home',selected=null,category='Check-in',chosen='',filter='all',mailbox='received',theme=get('ping_theme','day'),notes=get('ping_notes',{}),last=get('ping_last',null),busy=false,recorder=null,stream=null,recStart=0,recordTimer=null,recordReady=false,pagerIndex=0,voiceIndex=0,chatPeer=null,chatMessages=[],chatBusy=false,chatTimer=null,nudgeLast=0,nudgeCount=0;const bank={'Affection':['Thinking of you ❤️','Miss you!','Sending a big hug','You mean a lot to me','Love you!','Can’t wait to see you'],'Check-in':['How are you?','Have you eaten?','Reached home safely?','Everything okay?','Good morning!','Good night!','Call me when free'],'Plans':['Coffee soon?','Free for dinner?','Want to hang out?','See you later!','On my way!','Where shall we meet?'],'Encouragement':['You got this!','Proud of you!','Good luck today','Keep going!','Take a break, okay?'],'Singlish':['Jiak ba buay?','Eh where you?','Steady lah!','Onz lah!','Mai tu liao!','Don’t kancheong!','Can can!'],'Funny':['SOS need snacks','You have been summoned','Bored. Entertain me.','Paging the VIP','Plot twist!','Your kopi is calling'],'Important':['Please call me ASAP','Need your help','Are you safe?','Please reply when you can']};async function api(path,method='GET',body=null,raw=false){const headers={Authorization:'Bearer '+token};if(body&&!raw)headers['content-type']='application/json';if(raw)headers['content-type']=body.type||'audio/webm';const r=await fetch('/api'+path,{method,headers,body:body?(raw?body:JSON.stringify(body)):undefined,cache:'no-store'});const v=await r.json();if(!r.ok)throw Error(v.error||'Request failed');return v}async function uploadAudio(blob){const r=await fetch('/api/upload',{method:'POST',headers:{Authorization:'Bearer '+token,'content-type':blob.type},body:blob});const v=await r.json();if(!r.ok)throw Error(v.error||'Upload failed');return v}function toast(t){const e=$('#notice');if(e){e.textContent=t;e.hidden=false;setTimeout(()=>{if(e)e.hidden=true},4500)}else alert(t)}async function refresh(){if(!token)return;try{const [a,b,c]=await Promise.all([api('/me'),api('/friends'),api('/messages')]);me=a.me;friends=b.friends;msgs=c.messages;checkNudges();if(page!=='broadcast'&&!recordReady)render()}catch(e){if(e.message.includes('Invalid session')){localStorage.removeItem('ping_token');token=null;me=null;render()}else toast(e.message)}}function nav(p,id){if(p==='messenger'){chatPeer=null;loadMessengerFriends()}if(p!=='chat'&&chatTimer){clearInterval(chatTimer);chatTimer=null}if((p==='pager'||p==='radio')&&!id&&!friends.some(f=>f.id===selected)){selected=friends.some(f=>f.id===last)?last:null}if(p!=='broadcast'&&radioAudio){radioAudio.pause();radioAudio=null;radioPlaying=''}if(p==='pager')pagerIndex=0;if(p==='radio')voiceIndex=0;if(p==='home')selected=null;page=p;if(id)selected=id;chosen='';render();window.scrollTo(0,0)}function friend(){return friends.find(x=>x.id===selected)}function button(label,action,cls=''){return `<button class="${cls}" onclick="${action}">${label}</button>`}function unread(kind){return msgs.filter(m=>m.receiver_id===me?.id&&!m.read_at&&(!kind||m.kind===kind)).length}function unreadBadge(){const n=unread();return n?`<span class="unread-badge" aria-label="${n} unread messages">${n>99?'99+':n}</span>`:''}function openMailbox(which){mailbox=which==='sent'?'sent':'received';filter='all';nav(mailbox==='sent'?'outbox':'inbox')}function back(){selected=null;nav('home')}function receivedHistory(kind){return msgs.filter(m=>m.receiver_id===me?.id&&m.kind===kind).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,25)}
function senderName(m){const f=friends.find(x=>x.id===m.sender_id);return f?(notes[f.id]?.name||f.name):'Former friend'}
function orderedRecipients(){return [...friends].sort((a,b)=>Number(!!notes[b.id]?.star)-Number(!!notes[a.id]?.star)||(notes[a.id]?.name||a.name).localeCompare(notes[b.id]?.name||b.name))}
function recipientSelector(){const f=friend();return `<label class="recipient-picker">Send to <select id="recipientSelect" onchange="chooseRecipient(this.value)"><option value="">Choose a contact…</option>${orderedRecipients().map(x=>`<option value="${esc(x.id)}" ${selected===x.id?'selected':''}>${notes[x.id]?.star?'★ ':''}${esc(notes[x.id]?.name||x.name)}</option>`).join('')}</select></label>${!friends.length?'<p class="small muted">Add a friend first to send messages.</p>':f?`<p class="small muted">Selected: ${esc(notes[f.id]?.name||f.name)}</p>`:''}`}
function chooseRecipient(id){selected=friends.some(f=>f.id===id)?id:null;if(selected){last=selected;put('ping_last',last)}const hint=document.getElementById('recipient-hint');if(hint)hint.textContent=selected?'Ready to send':'Choose a contact before sending'}
function pagerHistory(){return receivedHistory('page')}
function pagerStep(d){const h=pagerHistory();pagerIndex=Math.max(0,Math.min(h.length-1,pagerIndex+d));render()}
function pagerView(){const h=pagerHistory(),m=h[pagerIndex];return `<div class="pager-device"><div class="pager-top"><span>PING LAH! SG</span><span>● PAGER / 01</span></div><div class="pager-bezel"><div class="pager-lcd"><div class="lcd-meta"><span>▂▄▆ ▣</span><span>PAGE ${h.length?pagerIndex+1:0}/${h.length}</span><span>▰</span></div><div class="lcd-label">${m?'FROM '+esc(senderName(m)):'READY TO PAGE'}</div><div class="lcd-code">${m?'PING!':'HELLO!'}</div><div class="lcd-message">${esc(m?.body||'Received pages will appear here.')}</div><div class="lcd-date">${m?new Date(m.created_at).toLocaleString():'NO RECEIVED PAGE'}</div></div></div><div class="pager-controls"><button aria-label="Older received page" onclick="pagerStep(1)" ${!h.length||pagerIndex>=h.length-1?'disabled':''}>◀</button><div class="pager-lights"><i></i><i></i></div><button aria-label="Newer received page" onclick="pagerStep(-1)" ${!h.length||pagerIndex===0?'disabled':''}>▶</button></div><div class="pager-foot">${h.length?`${pagerIndex+1} of ${h.length} latest received pages`:'No received pages yet · latest 25 shown'}</div></div>`}
function voiceHistory(){return receivedHistory('voice')}
function voiceStep(d){const h=voiceHistory();voiceIndex=Math.max(0,Math.min(h.length-1,voiceIndex+d));render()}
function voiceDeviceHistory(){const h=voiceHistory(),m=h[voiceIndex];return `<div class="walkie-received" aria-label="Incoming voice messages"><div class="walkie-received-heading">INCOMING · ${h.length?voiceIndex+1:0}/${h.length}</div><div class="walkie-received-from">${m?`FROM ${esc(senderName(m))}`:'NO RECEIVED TRANSMISSIONS'}</div><div class="walkie-received-date">${m?new Date(m.created_at).toLocaleString():'Messages from friends appear here'}</div></div>`}
function walkieHistoryControls(){const h=voiceHistory(),m=h[voiceIndex];return `<div class="walkie-transport"><button onclick="voiceStep(1)" aria-label="Previous older recording" ${!m||voiceIndex>=h.length-1?'disabled':''}>◀</button><button class="walkie-listen" onclick="playVoice('${m?.id||''}','walkie-audio')" ${!m?'disabled':''}>▶ PLAY</button><button onclick="voiceStep(-1)" aria-label="Next newer recording" ${!m||voiceIndex===0?'disabled':''}>▶</button></div><div id="walkie-audio" class="walkie-audio"></div>`}
async function enablePush(){try{if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window))throw Error('This browser does not support Web Push. On iPhone, add Ping Lah! to your Home Screen and open it from the icon.');if(Notification.permission==='denied')throw Error('Notifications are blocked. Enable them in your phone settings.');const key=(await api('/push/public-key')).publicKey;if(!key)throw Error('Cloudflare push keys are not configured yet');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notification permission was not granted');const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub){const b64=key.replace(/-/g,'+').replace(/_/g,'/');const raw=atob(b64+'='.repeat((4-b64.length%4)%4));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(raw,c=>c.charCodeAt(0))})}await api('/push/subscribe','POST',{subscription:sub.toJSON()});toast('Notifications enabled! Send yourself a test ping.');updatePushStatus()}catch(e){toast(e.message)}}
async function disablePush(){try{const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();if(sub){await api('/push/unsubscribe','POST',{endpoint:sub.endpoint});await sub.unsubscribe()}toast('Notifications disabled');updatePushStatus()}catch(e){toast(e.message)}}
async function testPush(){const el=document.getElementById('push-test-result');if(el)el.textContent='Contacting push provider…';try{const r=await api('/push/test','POST',{});if(el)el.textContent=`Push provider accepted ${r.sent} of ${r.devices} device(s).${r.expired?' '+r.expired+' expired.':''} ${r.failed?'Failed: '+r.errors.join('; '):'Check your notifications now.'}`;if(r.failed||!r.sent)toast('Push delivery failed — see diagnostic below.');else toast('Push provider accepted the test ping.')}catch(e){if(el)el.textContent='Test failed: '+e.message;toast('Test failed: '+e.message)}}
async function updatePushStatus(){const el=document.getElementById('push-status');if(!el)return;try{if(!('PushManager' in window)||!('serviceWorker' in navigator)){el.textContent='Install this web app to your Home Screen to enable notifications on iPhone.';return}const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();el.textContent=sub&&Notification.permission==='granted'?'Notifications enabled on this device.':'Notifications are not enabled on this device.'}catch{el.textContent='Notifications not available in this browser.'}}
function pushSettings(){return `<section class="panel"><h2>🔔 Notifications</h2><p class="muted">Get a real ping when a friend sends a pager or voice message — even when the app is closed.</p><p class="small" id="push-status">Checking notification status…</p><div class="row">${button('🔔 Enable notifications','enablePush()','btnaccent')}${button('Send test ping','testPush()','pill')}${button('Turn off','disablePush()','pill')}</div><p class="small" id="push-test-result" role="status" aria-live="polite"></p><p class="small muted">iPhone: Add to Home Screen in Safari, then open from the app icon before enabling. Android: Chrome supports Web Push with permission. Notification sounds are controlled by your phone.</p></section>`}
function renderHeader(){return `<header class="top"><div class="brand"><img src="/icon.svg" alt="" width="47" height="47"><div>Ping <span>Lah!</span> SG<small>A little ping. A closer connection.</small></div></div>${button(theme==='day'?'☾':'☀','toggleTheme()','pill')}</header>`}function toggleTheme(){theme=theme==='day'?'night':'day';put('ping_theme',theme);render()}function contactRow(f){const n=notes[f.id]||{};return `<div class="contact"><button class="grow plain" onclick="nav('detail','${f.id}')">${n.star?'⭐':'👤'} ${esc(n.name||f.name)}</button>${button('📟',`nav('pager','${f.id}')`,'pill')}${button('🎙️',`nav('radio','${f.id}')`,'pill')}${button('💬',`openChat('${f.id}')`,'pill')}</div>`}function msgRow(m){const other=friends.find(f=>f.id===(m.sender_id===me.id?m.receiver_id:m.sender_id));const inbound=m.receiver_id===me.id;return `<div class="message"><div><b>${m.kind==='page'?'📟':'🎙️'} ${esc(other?(notes[other.id]?.name||other.name):'Former friend')}</b> <span class="muted small">${inbound?'Received':'Sent'} · ${new Date(m.created_at).toLocaleString()}</span></div>${m.kind==='page'?`<div class="screen">${esc(m.body)}</div>`:`<div class="voice-playback"><button class="pill" onclick="playVoice('${m.id}')">▶ Load voice message</button><div id="audio-${m.id}"></div></div>`}<div class="small muted">${inbound&&!m.read_at?'<span class="new-label">● Unread</span> '+button('Mark read',`markRead('${m.id}')`,'pill'):''} Expires ${new Date(m.expires_at).toLocaleString()}</div></div>`}function render(){document.body.className=(theme==='night'?'dark':'')+(page==='chat'?' chat-active':'');let o=`<main class="shell">${renderHeader()}<div id="notice" class="notice" hidden></div>`;if(!me){o+=`<section class="panel hero"><h1>Welcome to Ping Lah!</h1><p>A retro pager and walkie-talkie for keeping in touch with friends. Create your private account on this device.</p><label>Your display name<input id="newName" maxlength="60" placeholder="What should friends call you?"></label>${button('Create my account','register()','btnaccent btnwide')}<hr><h3>Already have an account?</h3><label>Recovery code<input id="recoveryInput" autocomplete="off" placeholder="Paste your saved recovery code"></label>${button('Recover my account','recoverAccount()','btnmint btnwide')}<p class="small">Keep your browser data safe: this version uses a device-specific login token. Clearing site data may make your account inaccessible. See README for limitations.</p></section>`}else{if(page!=='home'&&page!=='chat')o+=button('← Back',"back()",'back');if(page==='home'){const f=friends.find(x=>x.id===last);o+=`<p class="account-indicator">Signed in as <b>${esc(me.name)}</b> · Code <b>${esc(me.code)}</b></p><section class="panel hero"><h1>Old-school vibes. Real connections.</h1><p>Page a friend or send a voice transmission. No feeds. No fuss. Just a little ping.</p><div class="row"><span class="notification-wrap">${button('📟 Pager',"nav('pager')",'pill')}${unread('page')?`<span class="unread-badge mini">${unread('page')}</span>`:''}</span><span class="notification-wrap">${button('🎙️ Walkie-talkie',"nav('radio')",'pill')}${unread('voice')?`<span class="unread-badge mini">${unread('voice')}</span>`:''}</span><span class="nudge-target ${nudgeCount?'nudge-shake':''}">${button('💬 Messenger'+(nudgeCount?' · '+nudgeCount+' Ping!':''),"nav('messenger')",'pill')}</span></div><p class="small muted">Communication: Pager · Walkie-talkie · Messenger</p><div class="solo-radio">${button('📻 Listen to radio',"nav('broadcast')",'pill')}</div></section><section class="panel"><h2>Quick access</h2><div class="grid"><button class="tile inbox-tile" onclick="openMailbox('received')"><span>📬 Inbox</span>${unreadBadge()}</button>${button('📤 Outbox',"openMailbox('sent')",'tile')}${button('👥 Contacts',"nav('contacts')",'tile')}${button('➕ Add friend',"nav('add')",'tile')}${button('🔗 Share my code',"nav('share')",'tile')}${button('⚙️ My profile',"nav('profile')",'tile')}</div>${f?`<h3>Last friend: ${esc(notes[f.id]?.name||f.name)}</h3><div class="row">${button('📟 Page again',`nav('pager','${f.id}')`,'btnaccent')}${button('🎙️ Talk again',`nav('radio','${f.id}')`,'btnmint')}</div>`:''}</section><section class="panel"><h2>⭐ Close friends</h2>${friends.filter(f=>notes[f.id]?.star).map(contactRow).join('')||'<p class="muted">Star friends from their profiles.</p>'}</section>${pushSettings()}${support()}`}
 if(page==='messenger')o+=messengerListView();
 if(page==='chat')o+=chatView();
 if(page==='profile')o+=profileView();
 if(page==='share')o+=`<section class="panel"><h1>Your friend code</h1><div class="screen bigcode">${esc(me.code)}</div><p>Share this code. Your friend can copy and paste it into Add friend.</p>${button('📋 Copy friend code','copyFriendCode()','btnaccent btnwide')}${button('Share friend code','shareFriendCode()','btnmint btnwide')}<p class="small muted">Friendships are saved in the cloud until either person removes the connection.</p></section>`;
 if(page==='add')o+=`<section class="panel"><h1>Add a friend</h1><p>Enter their code to create a two-way friendship.</p><label>Friend code<input id="friendCode" value="${esc(new URLSearchParams(location.search).get('add')||'')}" maxlength="8" placeholder="e.g. 7K3M8P2Q"></label>${button('Connect with friend','addFriend()','btnaccent btnwide')}</section>`;
 if(page==='contacts')o+=`<section class="panel"><h1>Contact book</h1>${button('＋ Add a friend',"nav('add')",'btnaccent btnwide')}${friends.map(contactRow).join('')||'<p>No friends yet. Share your code!</p>'}</section>`;
 if(page==='detail'){const f=friend(),n=notes[f?.id]||{};o+=f?`<section class="panel"><h1>${esc(n.name||f.name)}</h1><p class="muted">Their friend code: ${esc(f.code)}</p>${button(n.star?'★ Close friend':'☆ Star friend','star()','pill')}<label>My nickname for this friend<input id="nick" value="${esc(n.name||'')}" maxlength="70" placeholder="Optional nickname"></label><label>Private notes<textarea id="friendNotes" placeholder="Things to remember...">${esc(n.text||'')}</textarea></label>${button('Save contact notes','saveNotes()','btnmint btnwide')}<div class="row actions">${button('📟 Pager',"nav('pager')",'btnaccent grow')}${button('🎙️ Walkie-talkie',"nav('radio')",'btnmint grow')}${button('💬 Messenger',`openChat('${f.id}')`,'btnaccent grow')}</div>${button('Remove friendship','removeFriend()','btnwide danger')}</section>`:'<p>Friend unavailable.</p>'}
 if(page==='pager'){const f=friend();o+=`<section class="panel pager-section"><h1>📟 Pager</h1><p class="muted">Read received pages on the screen, or send a new one below. Pages expire after 7 days.</p>${pagerView()}<div class="compose-pager"><h2>Send a little ping</h2>${recipientSelector()}<div id="recipient-hint" class="small muted">${selected?'Ready to send':'Choose a contact before sending'}</div><p class="muted small">Choose a category, then select your message.</p><div class="pager-categories">${Object.keys(bank).map(k=>button(esc(k),`setCategory('${k}')`,'pill '+(k===category?'selected':''))).join('')}</div><div class="pager-options">${bank[category].map(x=>button(esc(x),`pick(${JSON.stringify(x).replace(/"/g,'&quot;')})`,'pager-option '+(chosen===x?'chosen':''))).join('')}</div><div class="pager-preview"><span>YOUR OUTGOING PAGE</span><strong id="preview">${esc(chosen||'Tap a message above...')}</strong></div><div class="emoji-picker"><span>Emoji:</span>${['❤️','🥰','😘','😂','🥹','😊','👍','🎉','💪','🙏','👋','💕'].map(e=>button(e,`addEmoji('${e}')`,'emoji-btn')).join('')}${button('Clear emoji','clearEmoji()','pill')}</div>${button('📟 SEND PAGE ↗','sendPage()','btnaccent btnwide')}</div></section>`}
 if(page==='radio'){const f=friend();o+=`<section class="panel"><h1>🎙️ Walkie-talkie</h1><p class="muted">Listen to received transmissions, or record a message for a friend.</p><div class="walkie-device"><div class="walkie-antenna"></div><div class="walkie-head"><span>PING LAH! • TRANSCEIVER</span><span class="walkie-led">●</span></div><div class="walkie-screen"><div class="walkie-screen-top">CH 01 · VOICE MESSAGE</div><div id="radioStatus">READY TO TRANSMIT<br>Tap START to activate microphone</div><div class="record-clock" id="recordClock" aria-live="off">00:00 / 00:12</div><div class="record-progress"><div id="recordProgress"></div></div><div class="walkie-screen-bottom">◢◣ SIGNAL · DIGITAL</div><div class="walkie-screen-incoming">${voiceDeviceHistory()}</div></div><div class="walkie-speaker">${Array.from({length:8},()=>'<i></i>').join('')}</div>${recipientSelector()}<div class="walkie-action-row"><button class="ptt walkie-ptt" id="ptt" onclick="radioClick()">🎙️ START<br>RECORDING</button>${walkieHistoryControls()}</div><p class="walkie-hint" id="radioHint">Tap again to stop and send · maximum 12 seconds</p><div class="walkie-footer">PING LAH! SG · PUSH TO TALK</div></div><div class="walkie-send"><p class="small muted">Microphone access is reused while this page stays open. Your browser controls permission between visits.</p></div><p class="small muted">Voice notes can be replayed until they expire 24 hours after sending. A message isn't a live radio call.</p></section>`}
 if(page==='broadcast'){o+=broadcastView()}
 if(page==='inbox'||page==='outbox'){const incoming=page==='inbox';const shown=msgs.filter(m=>(incoming?m.receiver_id===me.id:m.sender_id===me.id)&&(filter==='all'||m.kind===filter));o+=`<section class="panel"><h1>${incoming?'📬 Inbox':'📤 Outbox'} ${incoming?unreadBadge():''}</h1><p class="small muted">Signed in as ${esc(me.name)} · ${esc(me.code)}. Only messages ${incoming?'sent to':'sent by'} this account appear here.</p><div class="row">${['all','page','voice'].map(x=>button(x==='all'?'All':x==='page'?'📟 Pager':'🎙️ Voice',`setFilter('${x}')`,'pill '+(filter===x?'selected':''))).join('')}</div>${shown.map(msgRow).join('')||`<p>No ${incoming?'received':'sent'} messages yet.</p>`}<p class="small muted">Inbox refreshes automatically every 15 seconds while open.</p></section>`}}
 o+=`<footer>Made with care by <b>Matthew Kwong</b> · © 2026<br><span class="small">An AIYOU! Technologies project</span></footer></main>`;$('#app').innerHTML=o;if(page==='chat'){setChatViewport();const log=$('#chat-log');if(log)log.scrollTop=log.scrollHeight}}
 function support(){return `<section class="panel"><h2>Enjoying Ping Lah!?</h2><p>If our little app brings you closer to someone, an optional kopi contribution helps keep it running. No pressure at all — thank you!</p><h3>DBS PayLah!</h3><img class="qr" src="/assets/paylah-qr.png" alt="PayLah support QR"><h3>PayNow</h3><img class="qr" src="/assets/paynow-qr.png" alt="PayNow support QR"></section>`}async function register(){const name=$('#newName').value.trim();if(!name)return toast('Please enter your name');try{const r=await fetch('/api/register',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name})});const x=await r.json();if(!r.ok)throw Error(x.error);token=x.token;localStorage.setItem('ping_token',token);showRecovery(x.recovery);await refresh();const invite=new URLSearchParams(location.search).get('add');if(invite)nav('add')}catch(e){toast(e.message)}}async function addFriend(){try{await api('/friends','POST',{code:$('#friendCode').value.trim()});history.replaceState(null,'',location.pathname);await refresh();nav('contacts');toast('Friend connected!')}catch(e){toast(e.message)}}async function removeFriend(){if(!confirm('Remove this friendship for both people?'))return;try{await api('/friends/'+selected,'DELETE');delete notes[selected];put('ping_notes',notes);await refresh();nav('contacts')}catch(e){toast(e.message)}}function star(){const n=notes[selected]||{};n.star=!n.star;notes[selected]=n;put('ping_notes',notes);render()}function saveNotes(){notes[selected]={...notes[selected],name:$('#nick').value.trim(),text:$('#friendNotes').value};put('ping_notes',notes);render();toast('Notes saved on this device')}function invite(){return location.origin+'/?add='+encodeURIComponent(me.code)}async function copyFriendCode(){try{await navigator.clipboard.writeText(me.code);toast('Friend code copied!')}catch{prompt('Copy your friend code',me.code)}}async function shareFriendCode(){if(navigator.share)try{await navigator.share({text:'Add me on Ping Lah! SG — friend code: '+me.code})}catch{}else copyFriendCode()}async function copyInvite(){try{await navigator.clipboard.writeText(invite());toast('Invitation link copied')}catch{prompt('Copy this link',invite())}}async function shareInvite(){if(navigator.share)try{await navigator.share({title:'Join me on Ping Lah! SG',text:'Connect with me on Ping Lah! SG',url:invite()})}catch{}else copyInvite()}function showRecovery(code){if(!code)return;const text='PING LAH! SG RECOVERY CODE\n'+code+'\nSave this somewhere safe. It can only be used once and replaces your previous login.';window.prompt('IMPORTANT: Copy and save your one-time recovery code now. It will not be shown again.',text)}
async function recoverAccount(){const recovery=$('#recoveryInput')?.value.trim();if(!recovery)return toast('Enter your recovery code');try{const r=await fetch('/api/recover',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({recovery})});const x=await r.json();if(!r.ok)throw Error(x.error||'Recovery failed');token=x.token;localStorage.setItem('ping_token',token);showRecovery(x.recovery);page='home';await refresh();toast('Account recovered. Save your NEW recovery code.')}catch(e){toast(e.message)}}
