const RADIO_COUNTRIES={SG:'Singapore',MY:'Malaysia',ID:'Indonesia',TH:'Thailand',VN:'Vietnam',PH:'Philippines',JP:'Japan',KR:'South Korea',CN:'China',TW:'Taiwan',HK:'Hong Kong',IN:'India',AU:'Australia',NZ:'New Zealand',GB:'United Kingdom',US:'United States',CA:'Canada',FR:'France',DE:'Germany',IT:'Italy',ES:'Spain',NL:'Netherlands',AE:'United Arab Emirates'};
let radioCountry=get('ping_radio_country',''),radioStations=[],radioBusy=false,radioMessage='Select a country or detect your location to find stations.',radioAudio=null,radioPlaying='',radioRequest=0,radioIndex=0,radioFavorites=get('ping_radio_favorites',[]),radioActive=null;
function guessCountry(){const tz=Intl.DateTimeFormat().resolvedOptions().timeZone||'';const map={'Asia/Singapore':'SG','Asia/Kuala_Lumpur':'MY','Asia/Jakarta':'ID','Asia/Bangkok':'TH','Asia/Ho_Chi_Minh':'VN','Asia/Manila':'PH','Asia/Tokyo':'JP','Asia/Seoul':'KR','Asia/Shanghai':'CN','Asia/Taipei':'TW','Asia/Hong_Kong':'HK','Asia/Kolkata':'IN','Australia/Sydney':'AU','Pacific/Auckland':'NZ','Europe/London':'GB','Europe/Paris':'FR','Europe/Berlin':'DE','America/New_York':'US','America/Los_Angeles':'US','America/Toronto':'CA','Asia/Dubai':'AE'};return map[tz]||((navigator.language||'').split('-')[1]||'SG').toUpperCase()}
function radioFreq(st){if(!st)return '—';const m=String(st.name||'').match(/(?:^|\D)(8[7-9]\.\d|9\d\.\d|10[0-7]\.\d)(?:\s*FM|\b|$)/i);return m?m[1]+' FM':'WEB';}
function radioKey(st){return st?.stationuuid||st?.url||''}
function isRadioSaved(st){return radioFavorites.some(f=>radioKey(f)===radioKey(st))}
function toggleRadioFavorite(i){const st=radioStations[Number(i)];if(!st)return;const key=radioKey(st);radioFavorites=isRadioSaved(st)?radioFavorites.filter(f=>radioKey(f)!==key):[...radioFavorites,st].slice(-60);put('ping_radio_favorites',radioFavorites);updateRadioList()}
function playSavedStation(i){const st=radioFavorites[Number(i)];if(!st)return;let n=radioStations.findIndex(x=>radioKey(x)===radioKey(st));if(n<0){radioStations=[st,...radioStations];n=0}radioIndex=n;render();playStation(n)}
function radioRows(){return radioStations.map((st,i)=>`<div class="station-row"><button class="radio-heart" aria-label="${isRadioSaved(st)?'Remove saved station':'Save station'}" onclick="toggleRadioFavorite(${i})">${isRadioSaved(st)?'♥':'♡'}</button><div class="grow"><b>${esc(st.name)}</b><div class="small muted">${esc(radioFreq(st))} · ${esc(st.tags||'Internet radio')}</div></div><button class="pill" onclick="playStation(${i})">▶ Listen</button></div>`).join('')}
function savedRadioRows(){return radioFavorites.length?radioFavorites.map((st,i)=>`<div class="station-row"><span class="radio-heart saved-heart">♥</span><div class="grow"><b>${esc(st.name)}</b><div class="small muted">${esc(st.country||'Saved')} · ${esc(radioFreq(st))}</div></div><button class="pill" onclick="playSavedStation(${i})">▶ Play</button></div>`).join(''):'<p class="small muted">Tap ♡ beside a station to save it here for quick access.</p>'}
