function retroSound(type){if(!get('ping_retro_sounds',false)||document.visibilityState!=='visible')return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C();const notes=type==='nudge'?[540,760,540]:type==='online'?[580,780]:[760,980];notes.forEach((freq,i)=>{const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+i*.105;o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.075,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+.09);o.connect(g).connect(ctx.destination);o.start(t);o.stop(t+.1)});setTimeout(()=>ctx.close().catch(()=>{}),800)}catch(e){console.warn('Sound unavailable',e)}}
