function choosePersonalMessage(value){if(value){const field=$('#profile-message');if(field){field.value=value}}}
function profileView(){return `<section class="panel msn-panel"><h1>⚙️ My profile</h1><p class="muted">Your friend code stays the same when you change your name.</p><label>Display name<input id="profile-name" maxlength="60" value="${esc(me.name)}"></label><label>Messenger status<select id="profile-status">${statusOptions.map(([k,v])=>`<option value="${k}" ${me.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Retro buddy avatar<select id="profile-avatar">${buddyAvatars.map((a,i)=>`<option value="${a}" ${(me.avatar||'🙂')===a?'selected':''}>${a} ${buddyAvatarNames[i]}</option>`).join('')}</select></label><label class="setting-check"><input type="checkbox" id="retro-sounds" ${get('ping_retro_sounds',false)?'checked':''} onchange="toggleRetroSounds(this.checked)"> Retro Messenger sounds (while app is open)</label><label class="setting-check"><input type="checkbox" ${get('ping_online_alerts',true)?'checked':''} onchange="put('ping_online_alerts',this.checked)"> Friend online alerts (while app is open)</label><label>Quick personal message<select id="profile-message-preset" onchange="choosePersonalMessage(this.value)"><option value="">✨ Pick a classic MSN-style message…</option>${personalMessagePresets.map(p=>`<option value="${esc(p)}">${esc(p)}</option>`).join('')}</select></label><label>Personal message<input id="profile-message" maxlength="120" placeholder="Or write your own message… 🎵" value="${esc(me.status_message||'')}"></label><p class="small muted">Pick a classic or type your own. Tap Save profile to keep it.</p>${button('Save profile','saveProfile()','btnaccent btnwide')}<p class="small muted">Online and Away reflect recent activity. Appear Offline hides your presence.</p></section>`}
async function saveProfile(){try{const name=$('#profile-name').value.trim(),status=$('#profile-status').value,status_message=$('#profile-message').value.trim(),avatar=$('#profile-avatar').value;if(!name)throw Error('Enter a display name');await api('/me','PATCH',{name,status,status_message,avatar});const confirmed=await api('/me');me=confirmed.me;if(me.avatar!==avatar){throw Error('Avatar was not saved. Please check that the v27 backend is deployed.')}await refresh();toast('Profile saved · '+avatar)}catch(e){toast(e.message)}}
function statusText(f){const x=messengerProfiles[f.id]||f;const st=x.status||'offline';if(st==='offline'||!x.last_seen||Date.now()-Number(x.last_seen)>120000)return '⚪ Offline';return (statusOptions.find(o=>o[0]===st)||statusOptions[4])[1]}
function messengerListView(){const fs=orderedRecipients();return `<section class="panel msn-panel"><div class="msn-title">💬 Ping Lah! Messenger <span>● ● ●</span></div><div class="msn-my-profile"><strong>${esc(me.name)}</strong> <span>${esc(statusText(me))}</span><div class="small muted">${esc(me.status_message||'Set your personal message in My profile')}</div>${button('Edit my name & status',"nav('profile')",'pill')}</div><h2>Friends (${fs.length})</h2>${fs.map(f=>`<button class="msn-friend" onclick="openChat('${f.id}')"><span class="msn-avatar">${esc(buddyAvatar(f))}</span><span><strong>${esc(notes[f.id]?.name||f.name)}</strong><small>${esc(statusText(f))}${messengerProfiles[f.id]?.status_message?' · '+esc(messengerProfiles[f.id].status_message):''}</small></span><span>›</span></button>`).join('')||'<p class="muted">Add a friend to start chatting.</p>'}<p class="small muted">Private one-to-one conversations. Text and emoji only.</p></section>`}
async function loadMessengerFriends(){try{const r=await api('/messenger/presence');messengerProfiles=Object.fromEntries((r.friends||[]).map(x=>[x.id,x]));if(r.me)me={...me,...r.me};if(page==='messenger')render()}catch(e){console.warn('Messenger friends',e)}}
async function sendNudge(){if(!chatPeer)return;const peer=chatPeer;const f=friends.find(x=>x.id===peer);const name=notes[peer]?.name||f?.name||'your friend';try{await api('/messenger/nudge/'+encodeURIComponent(peer),'POST');showChatFeedback('✨ You’ve sent '+name+' a nudge!');const b=document.querySelector('.msn-chat-nudge');if(b){b.classList.remove('nudge-shake');void b.offsetWidth;b.classList.add('nudge-shake')}retroSound('nudge')}catch(e){showChatFeedback('Could not send nudge: '+e.message)}}
async function checkNudges(){if(nudgePollBusy)return;nudgePollBusy=true;try{const r=await api('/messenger/nudges');if(r.count){nudgeCount=r.count;const names=[...new Set((r.nudges||[]).map(n=>notes[n.sender_id]?.name||friends.find(f=>f.id===n.sender_id)?.name||'A friend'))];const message='✨ '+(names.length===1?names[0]+' nudged you!':names.length+' friends nudged you!');if(page==='chat')showChatFeedback(message);else toast(message);retroSound('nudge');if(page==='home')render();if(page==='messenger')render();setTimeout(()=>{nudgeCount=0;if(page==='home')render()},4000)}}catch(e){console.warn('Nudge check',e)}finally{nudgePollBusy=false}}
function openChat(id){if(!friends.some(f=>f.id===id))return toast('Friend unavailable');chatPeer=id;page='chat';chatMessages=[];chatLastIncoming='';render();loadChat();pollChatTyping();if(chatTimer)clearInterval(chatTimer);chatTimer=setInterval(()=>{if(page==='chat'&&document.visibilityState==='visible'){loadChat(true);pollChatTyping()}},3000)}
function chatView(){const f=friends.find(x=>x.id===chatPeer);if(!f)return '<section class="panel">Friend unavailable.</section>';return `<section class="msn-chat-window"><div class="msn-chat-header"><button class="msn-chat-back" onclick="closeChat()" aria-label="Back to friends">‹</button><div class="msn-chat-identity"><strong>💬 ${esc(notes[f.id]?.name||f.name)}</strong><small>${esc(statusText(f))}</small></div><button class="msn-chat-nudge" onclick="sendNudge()" title="Nudge friend">✨ Nudge</button></div><div id="chat-log" class="msn-log" role="log" aria-live="polite">${chatMessages.length?chatMessages.map(chatRow).join(''):'<p class="muted small">No messages yet. Say hello! 👋</p>'}</div><div class="msn-chat-bottom"><div id="chat-typing" class="msn-typing" aria-live="polite"></div><div class="msn-emoji">${['😊','😂','❤️','😭','👍','🥰','👋','🎉'].map(e=>`<button type="button" onclick="insertChatEmoji('${e}')">${e}</button>`).join('')}</div><form class="msn-compose" onsubmit="sendChat(event)"><input id="chat-input" oninput="onChatTyping()" maxlength="1000" autocomplete="off" placeholder="Type a message…" aria-label="Chat message" enterkeyhint="send"><button type="submit" class="btnaccent">Send ↗</button></form></div></section>`}
function closeChat(){if(chatTimer){clearInterval(chatTimer);chatTimer=null}chatPeer=null;nav('messenger')}
function setChatViewport(){if(!document.body.classList.contains('chat-active'))return;const v=window.visualViewport;document.documentElement.style.setProperty('--chat-height',(v?v.height:window.innerHeight)+'px');document.documentElement.style.setProperty('--chat-top',(v?v.offsetTop:0)+'px')}
if(window.visualViewport){window.visualViewport.addEventListener('resize',setChatViewport);window.visualViewport.addEventListener('scroll',setChatViewport)}window.addEventListener('resize',setChatViewport);

function chatRow(m){const mine=m.sender_id===me.id;const emoji=['❤️','😂','👍','😮','😢'];return `<div class="msn-message ${mine?'mine':'theirs'}"><div class="msn-message-head">${mine?'You':esc(friends.find(f=>f.id===m.sender_id)?.name||'Friend')} · ${new Date(m.created_at).toLocaleString()}</div><div class="msn-message-text">${esc(m.body)}</div><div class="msn-reactions">${emoji.map(e=>`<button title="React ${e}" onclick="reactChat('${m.id}','${e}')">${e}${m.reactions?.[e]?' '+m.reactions[e]:''}</button>`).join('')}</div></div>`}
function insertChatEmoji(e){const x=$('#chat-input');if(x){x.value+=e;x.focus()}}
async function loadChat(quiet=false){if(!chatPeer)return;const id=chatPeer;try{const r=await api('/messenger/chat/'+encodeURIComponent(id));if(page!=='chat'||chatPeer!==id)return;const incoming=r.messages||[];const newest=incoming.filter(m=>m.sender_id!==me.id).at(-1);if(newest&&chatLastIncoming&&newest.id!==chatLastIncoming)retroSound('message');if(newest)chatLastIncoming=newest.id;if(JSON.stringify(chatMessages)!==JSON.stringify(incoming)){const log=$('#chat-log');const nearBottom=!log||log.scrollHeight-log.scrollTop-log.clientHeight<100;const oldTop=log?.scrollTop||0;chatMessages=incoming;if(log){log.innerHTML=chatMessages.length?chatMessages.map(chatRow).join(''):'<p class="muted small">No messages yet. Say hello! 👋</p>';log.scrollTop=nearBottom?log.scrollHeight:oldTop}else render()}}catch(e){if(!quiet)toast(e.message)}}

async function sendChat(event){event.preventDefault();if(chatBusy)return;const input=$('#chat-input'),body=emojiShortcuts(input?.value.trim()||'');if(!body)return;chatBusy=true;try{await api('/messenger/chat/'+encodeURIComponent(chatPeer),'POST',{body});input.value='';await loadChat()}catch(e){toast(e.message)}finally{chatBusy=false}}
async function reactChat(id,emoji){try{await api('/messenger/react/'+encodeURIComponent(id),'POST',{emoji});await loadChat(true)}catch(e){toast(e.message)}}

setInterval(()=>{if(token&&document.visibilityState==='visible')pollMessengerExtras()},12000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&token)pollMessengerExtras()});
